import React, { useState, useEffect } from 'react';
import { Chart } from 'primereact/chart';

export default function PolarArea() {
    const [chartData, setChartData] = useState({});
    const [chartOptions, setChartOptions] = useState({});

    useEffect(() => {
        const targetElement = document.body ?? document.documentElement;
        const documentStyle = getComputedStyle(targetElement);
        const getColor = (variable) => {
            const value = documentStyle.getPropertyValue(variable)?.trim();
            if (value) {
                return value;
            }
            const rootStyle = getComputedStyle(document.documentElement);
            const rootValue = rootStyle.getPropertyValue(variable)?.trim();
            return rootValue;
        };
        const textColor = getColor('--uls-text-color');
        const surfaceBorder = getColor('--uls-default-border-color');
        const data = {
            datasets: [
                {
                    data: [11, 16, 7, 3, 14],
                    backgroundColor: [
                        getColor('--uls-primary-color'),
                        getColor('--uls-warning-color'),
                        getColor('--uls-success-color'),
                        getColor('--uls-secondary-text-color'),
                        getColor('--uls-text-color')
                    ],
                    label: 'My dataset'
                }
            ],
            labels: ['Red', 'Green', 'Yellow', 'Grey', 'Blue']
        };
        const options = {
            plugins: {
                legend: {
                    labels: {
                        color: textColor
                    }
                }
            },
            scales: {
                r: {
                    grid: {
                        color: surfaceBorder
                    }
                }
            }
        };

        setChartData(data);
        setChartOptions(options);
    }, []);

    return (
        <Chart type="polarArea" data={chartData} options={chartOptions} style={{ position: 'relative', width: '50%' }} />
    )

}